            if self.next_is(Token::Comma) {
                tables.push(self.parse_from_table()?);
            } else {
                // It's a join
                let join_type = self.parse_from_join()?;
                if let Some(join_type) = join_type {
                    let right = self.parse_from_table()?;
                    let left = tables.pop().unwrap();
                    let predicate = if self.next_is(Token::Keyword(Keyword::On)) {
                        Some(self.parse_expression()?)
                    } else {
                        None
                    };
                    tables.push(ast::From::Join {
                        left: Box::new(left),
                        right: Box::new(right),
                        r#type: join_type,
                        predicate,
                    });
