    }

    /// Consumes the next lexer token if it is the given token, returning true.
    fn next_is(&mut self, token: Token) -> bool {
        self.next_if(|t| t == &token).is_some()
    }

    /// Consumes the next lexer token if it's the expected token, or errors.
    fn expect(&mut self, expect: Token) -> Result<()> {
        let token = self.next()?;
        if token == expect {
            Ok(())
        } else {
            errinput!("expected {}, got {}", expect, token)
        }
    }

    /// Consumes the next lexer token if it is the given token. Equivalent to
    /// next_is(), but expresses intent better.
    fn skip(&mut self, token: Token) {
        self.next_is(token);
    }

    /// Peeks the next lexer token if any, but transposes it for convenience.
    fn peek(&mut self) -> Result<Option<&Token>> {
        Ok(self.lexer.peek())
    }

    /// Parses a SQL statement.
    fn parse_statement(&mut self) -> Result<ast::Statement> {
        match self.peek()? {
            Some(Token::Keyword(Keyword::Begin)) => self.parse_begin(),
            Some(Token::Keyword(Keyword::Commit)) => self.parse_commit(),
            Some(Token::Keyword(Keyword::Rollback)) => self.parse_rollback(),
            Some(Token::Keyword(Keyword::Explain)) => self.parse_explain(),
            Some(Token::Keyword(Keyword::Create)) => self.parse_create_table(),
            Some(Token::Keyword(Keyword::Drop)) => self.parse_drop_table(),
            Some(Token::Keyword(Keyword::Delete)) => self.parse_delete(),
            Some(Token::Keyword(Keyword::Insert)) => self.parse_insert(),
            Some(Token::Keyword(Keyword::Update)) => self.parse_update(),
            Some(Token::Keyword(Keyword::Select)) => self.parse_select(),
            _ => errinput!("unexpected token: {:?}", self.peek()?),
        }
    }

    /// Parses a BEGIN statement.
    fn parse_begin(&mut self) -> Result<ast::Statement> {
        self.next_is(Token::Keyword(Keyword::Begin));

        let read_only = self.next_is(Token::Keyword(Keyword::Read));
        if read_only {
            self.expect(Token::Keyword(Keyword::Only))?;
        }

        let as_of = if self.next_is(Token::Keyword(Keyword::As)) {
            self.expect(Token::Keyword(Keyword::Of))?;
            self.expect(Token::Keyword(Keyword::System))?;
            self.expect(Token::Keyword(Keyword::Time))?;
            self.expect(Token::Keyword(Keyword::Stamp))?;
            self.expect(Token::OpenParen)?;
            let version = self.next()?;
            match version {
                Token::Number(n) => Some(n.parse()?),
                _ => return errinput!("expected version number"),
            }
        } else {
            None
        };

        Ok(ast::Statement::Begin { read_only, as_of })
    }

    /// Parses a COMMIT statement.
    fn parse_commit(&mut self) -> Result<ast::Statement> {
        self.next_is(Token::Keyword(Keyword::Commit));
        Ok(ast::Statement::Commit)
    }

    /// Parses a ROLLBACK statement.
    fn parse_rollback(&mut self) -> Result<ast::Statement> {
        self.next_is(Token::Keyword(Keyword::Rollback));
        Ok(ast::Statement::Rollback)
    }

    /// Parses an EXPLAIN statement.
    fn parse_explain(&mut self) -> Result<ast::Statement> {
        self.next_is(Token::Keyword(Keyword::Explain));
        let stmt = Box::new(self.parse_statement()?);
        Ok(ast::Statement::Explain(stmt))
    }

    /// Parses a CREATE TABLE statement.
    fn parse_create_table(&mut self) -> Result<ast::Statement> {
        self.next_is(Token::Keyword(Keyword::Create));
        self.expect(Token::Keyword(Keyword::Table))?;

        let name = self.next_ident()?;

        self.expect(Token::OpenParen)?;

        let mut columns = Vec::new();
        loop {
            if self.next_is(Token::CloseParen) {
                break;
            }

            if !columns.is_empty() {
                self.expect(Token::Comma)?;
                if self.next_is(Token::CloseParen) {
                    break;
                }
            }

            columns.push(self.parse_create_table_column()?);
        }

        Ok(ast::Statement::CreateTable { name, columns })
    }

    /// Parses a CREATE TABLE column definition.
    fn parse_create_table_column(&mut self) -> Result<ast::Column> {
        let name = self.next_ident()?;

        // Parse datatype
        let datatype = match self.next()? {
            Token::Keyword(Keyword::Boolean) | Token::Keyword(Keyword::Bool) => DataType::Boolean,
            Token::Keyword(Keyword::Int) | Token::Keyword(Keyword::Integer) => DataType::Integer,
            Token::Keyword(Keyword::Float) | Token::Keyword(Keyword::Double) | Token::Keyword(Keyword::Real) => DataType::Float,
            Token::Keyword(Keyword::String) | Token::Keyword(Keyword::Text) | Token::Keyword(Keyword::Varchar) => DataType::String,
            other => return errinput!("expected datatype, got {}", other),
        };

        let mut primary_key = false;
        let mut nullable = None;
        let mut default = None;
        let mut unique = false;
        let mut index = false;
        let mut references = None;

        // Parse column constraints
        loop {
            match self.peek()? {
                Some(Token::Keyword(Keyword::Primary)) => {
                    self.next();
                    self.expect(Token::Keyword(Keyword::Key))?;
                    primary_key = true;
                }
                Some(Token::Keyword(Keyword::Not)) => {
                    self.next();
                    self.expect(Token::Keyword(Keyword::Null))?;
                    nullable = Some(false);
                }
                Some(Token::Keyword(Keyword::Null)) => {
                    self.next();
                    nullable = Some(true);
                }
                Some(Token::Keyword(Keyword::Default)) => {
                    self.next();
                    default = Some(self.parse_expression()?);
                }
                Some(Token::Keyword(Keyword::Unique)) => {
                    self.next();
                    unique = true;
                }
                Some(Token::Keyword(Keyword::Index)) => {
                    self.next();
                    index = true;
                }
                Some(Token::Keyword(Keyword::References)) => {
                    self.next();
                    references = Some(self.next_ident()?);
                }
                _ => break,
            }
        }

        Ok(ast::Column {
            name,
            datatype,
            primary_key,
            nullable,
            default,
            unique,
            index,
            references,
        })
    }

    /// Parses a DROP TABLE statement.
    fn parse_drop_table(&mut self) -> Result<ast::Statement> {
        self.next_is(Token::Keyword(Keyword::Drop));
        self.expect(Token::Keyword(Keyword::Table))?;

        let if_exists = self.next_is(Token::Keyword(Keyword::If));
        if if_exists {
            self.expect(Token::Keyword(Keyword::Exists))?;
        }

        let name = self.next_ident()?;

        Ok(ast::Statement::DropTable { name, if_exists })
    }

    /// Parses a DELETE statement.
    fn parse_delete(&mut self) -> Result<ast::Statement> {
        self.next_is(Token::Keyword(Keyword::Delete));
        self.expect(Token::Keyword(Keyword::From))?;

        let table = self.next_ident()?;

        let where_clause = if self.next_is(Token::Keyword(Keyword::Where)) {
            Some(self.parse_expression()?)
        } else {
            None
        };

        Ok(ast::Statement::Delete { table, r#where: where_clause })
    }

    /// Parses an INSERT statement.
    fn parse_insert(&mut self) -> Result<ast::Statement> {
        self.next_is(Token::Keyword(Keyword::Insert));
        self.expect(Token::Keyword(Keyword::Into))?;

        let table = self.next_ident()?;

        let columns = if self.next_is(Token::OpenParen) {
            let mut cols = Vec::new();
            loop {
                if self.next_is(Token::CloseParen) {
                    break;
                }
                if !cols.is_empty() {
                    self.expect(Token::Comma)?;
                    if self.next_is(Token::CloseParen) {
                        break;
                    }
                }
                cols.push(self.next_ident()?);
            }
            Some(cols)
        } else {
            None
        };

        self.expect(Token::Keyword(Keyword::Values))?;

        let mut values = Vec::new();
        loop {
            self.expect(Token::OpenParen)?;
            let mut row = Vec::new();
            loop {
                if self.next_is(Token::CloseParen) {
                    break;
                }
                if !row.is_empty() {
                    self.expect(Token::Comma)?;
                    if self.next_is(Token::CloseParen) {
                        break;
                    }
                }
                row.push(self.parse_expression()?);
            }
            values.push(row);

            if !self.next_is(Token::Comma) {
                break;
            }
        }

        Ok(ast::Statement::Insert { table, columns, values })
    }

    /// Parses an UPDATE statement.
    fn parse_update(&mut self) -> Result<ast::Statement> {
        self.next_is(Token::Keyword(Keyword::Update));

        let table = self.next_ident()?;

        self.expect(Token::Keyword(Keyword::Set))?;

        let mut set = std::collections::BTreeMap::new();
        loop {
            let column = self.next_ident()?;
            self.expect(Token::Equal)?;

            let value = if self.next_is(Token::Keyword(Keyword::Default)) {
                None
            } else {
                Some(self.parse_expression()?)
            };

            set.insert(column, value);

            if !self.next_is(Token::Comma) {
                break;
            }
        }

        let where_clause = if self.next_is(Token::Keyword(Keyword::Where)) {
            Some(self.parse_expression()?)
        } else {
            None
        };

        Ok(ast::Statement::Update { table, set, r#where: where_clause })
    }

    /// Parses a SELECT statement.
    fn parse_select(&mut self) -> Result<ast::Statement> {
        self.next_is(Token::Keyword(Keyword::Select));

        let select = self.parse_select_clause()?;

        let from = if self.next_is(Token::Keyword(Keyword::From)) {
            self.parse_from_clause()?
        } else {
            Vec::new()
        };

        let where_clause = if self.next_is(Token::Keyword(Keyword::Where)) {
            Some(self.parse_expression()?)
        } else {
            None
        };

        let group_by = if self.next_is(Token::Keyword(Keyword::Group)) {
            self.expect(Token::Keyword(Keyword::By))?;
            let mut cols = Vec::new();
            loop {
                cols.push(self.parse_expression()?);
                if !self.next_is(Token::Comma) {
                    break;
                }
            }
            cols
        } else {
            Vec::new()
        };

        let having = if self.next_is(Token::Keyword(Keyword::Having)) {
            Some(self.parse_expression()?)
        } else {
            None
        };

        let order_by = if self.next_is(Token::Keyword(Keyword::Order)) {
            self.expect(Token::Keyword(Keyword::By))?;
            let mut order = Vec::new();
            loop {
                let expr = self.parse_expression()?;
                let dir = if self.next_is(Token::Keyword(Keyword::Asc)) {
                    ast::Direction::Ascending
                } else if self.next_is(Token::Keyword(Keyword::Desc)) {
                    ast::Direction::Descending
                } else {
                    ast::Direction::default()
                };
                order.push((expr, dir));
                if !self.next_is(Token::Comma) {
                    break;
                }
            }
            order
        } else {
            Vec::new()
        };

        let limit = if self.next_is(Token::Keyword(Keyword::Limit)) {
            Some(self.parse_expression()?)
        } else {
            None
        };

        let offset = if self.next_is(Token::Keyword(Keyword::Offset)) {
            Some(self.parse_expression()?)
        } else {
            None
        };

        Ok(ast::Statement::Select {
            select,
            from,
            r#where: where_clause,
            group_by,
            having,
            order_by,
            limit,
            offset,
        })
    }

    /// Parses a SELECT clause, if present.
    fn parse_select_clause(&mut self) -> Result<Vec<(ast::Expression, Option<String>)>> {
        let mut expressions = Vec::new();

        loop {
            let expr = self.parse_expression()?;

            let alias = if self.next_is(Token::Keyword(Keyword::As)) {
                Some(self.next_ident()?)
            } else if self.peek()?.map_or(false, |t| matches!(t, Token::Ident(_))) {
                // Allow implicit alias without AS
                match self.peek()? {
                    Some(Token::Ident(name)) => {
                        self.next();
                        Some(name.clone())
                    }
                    _ => None,
                }
            } else {
                None
            };

            expressions.push((expr, alias));

            if !self.next_is(Token::Comma) {
                break;
            }
        }

        Ok(expressions)
    }

    /// Parses a FROM clause, if present.
    fn parse_from_clause(&mut self) -> Result<Vec<ast::From>> {
        let mut tables = Vec::new();

        tables.push(self.parse_from_table()?);

        while self.next_is(Token::Comma) || self.next_if_map(|t| match t {
            Token::Keyword(Keyword::Join) | Token::Keyword(Keyword::Inner) | Token::Keyword(Keyword::Left) | Token::Keyword(Keyword::Right) | Token::Keyword(Keyword::Cross) | Token::Keyword(Keyword::Outer) => Some(()),
            _ => None,
        }).is_some() {
            // Check for comma-separated tables
            if self.next_is(Token::Comma) {
                tables.push(self.parse_from_table()?);
            } else {
                // It's a join
                let join_type = self.parse_from_join()?;
                if let Some(join_type) = join_type {
                    let right = self.parse_from_table()?;
                    let left = tables.pop().unwrap();
                    let predicate = if self.next_is(Token::Keyword(Keyword::On)) {
                        Some(self.parse_expression()?)
                    } else {
                        None
                    };
                    tables.push(ast::From::Join {
                        left: Box::new(left),
                        right: Box::new(right),
                        r#type: join_type,
                        predicate,
                    });
                }
            }
        }

        Ok(tables)
    }

    // Parses a FROM table.
    fn parse_from_table(&mut self) -> Result<ast::From> {
        let name = self.next_ident()?;

        let alias = if self.next_is(Token::Keyword(Keyword::As)) {
            Some(self.next_ident()?)
        } else if self.peek()?.map_or(false, |t| matches!(t, Token::Ident(_))) {
            match self.peek()? {
                Some(Token::Ident(name)) => {
                    self.next();
                    Some(name.clone())
                }
                _ => None,
            }
        } else {
            None
        };

        Ok(ast::From::Table { name, alias })
    }

    // Parses a FROM JOIN type, if present.
    fn parse_from_join(&mut self) -> Result<Option<ast::JoinType>> {
        if self.next_is(Token::Comma) {
            return Ok(Some(ast::JoinType::Cross));
        }

        let join_type = if self.next_is(Token::Keyword(Keyword::Cross)) {
            self.expect(Token::Keyword(Keyword::Join))?;
            ast::JoinType::Cross
        } else if self.next_is(Token::Keyword(Keyword::Inner)) {
            self.expect(Token::Keyword(Keyword::Join))?;
            ast::JoinType::Inner
        } else if self.next_is(Token::Keyword(Keyword::Left)) {
            if self.next_is(Token::Keyword(Keyword::Outer)) {
                self.expect(Token::Keyword(Keyword::Join))?;
            } else {
                self.expect(Token::Keyword(Keyword::Join))?;
            }
            ast::JoinType::Left
        } else if self.next_is(Token::Keyword(Keyword::Right)) {
            if self.next_is(Token::Keyword(Keyword::Outer)) {
                self.expect(Token::Keyword(Keyword::Join))?;
            } else {
                self.expect(Token::Keyword(Keyword::Join))?;
            }
            ast::JoinType::Right
        } else if self.next_is(Token::Keyword(Keyword::Join)) {
            ast::JoinType::Inner
        } else {
            return Ok(None);
        };

        Ok(Some(join_type))
    }

    /// Parses a WHERE clause, if present.
    fn parse_where_clause(&mut self) -> Result<Option<ast::Expression>> {
        if self.next_is(Token::Keyword(Keyword::Where)) {
            Ok(Some(self.parse_expression()?))
        } else {
            Ok(None)
        }
    }

    /// Parses a GROUP BY clause, if present.
    fn parse_group_by_clause(&mut self) -> Result<Vec<ast::Expression>> {
        if self.next_is(Token::Keyword(Keyword::Group)) {
            self.expect(Token::Keyword(Keyword::By))?;
            let mut cols = Vec::new();
            loop {
                cols.push(self.parse_expression()?);
                if !self.next_is(Token::Comma) {
                    break;
                }
            }
            Ok(cols)
        } else {
            Ok(Vec::new())
        }
    }

    /// Parses a HAVING clause, if present.
    fn parse_having_clause(&mut self) -> Result<Option<ast::Expression>> {
        if self.next_is(Token::Keyword(Keyword::Having)) {
            Ok(Some(self.parse_expression()?))
        } else {
            Ok(None)
        }
    }

    /// Parses an ORDER BY clause, if present.
    fn parse_order_by_clause(&mut self) -> Result<Vec<(ast::Expression, ast::Direction)>> {
        if self.next_is(Token::Keyword(Keyword::Order)) {
            self.expect(Token::Keyword(Keyword::By))?;
            let mut order = Vec::new();
            loop {
                let expr = self.parse_expression()?;
                let dir = if self.next_is(Token::Keyword(Keyword::Asc)) {
                    ast::Direction::Ascending
                } else if self.next_is(Token::Keyword(Keyword::Desc)) {
                    ast::Direction::Descending
                } else {
                    ast::Direction::default()
                };
                order.push((expr, dir));
                if !self.next_is(Token::Comma) {
                    break;
                }
            }
            Ok(order)
        } else {
            Ok(Vec::new())
        }
    }

    /// Parses a LIMIT clause, if present.
    fn parse_limit_clause(&mut self) -> Result<Option<ast::Expression>> {
        if self.next_is(Token::Keyword(Keyword::Limit)) {
            Ok(Some(self.parse_expression()?))
        } else {
            Ok(None)
        }
    }

    /// Parses an OFFSET clause, if present.
    fn parse_offset_clause(&mut self) -> Result<Option<ast::Expression>> {
        if self.next_is(Token::Keyword(Keyword::Offset)) {
            Ok(Some(self.parse_expression()?))
        } else {
            Ok(None)
        }
    }

    /// Parses an expression using the precedence climbing algorithm.
    fn parse_expression(&mut self) -> Result<ast::Expression> {
        self.parse_precedence(0)
    }

    /// Precedence climbing expression parser.
    fn parse_precedence(&mut self, min_precedence: u8) -> Result<ast::Expression> {
        let mut lhs = self.parse_primary()?;

        loop {
            let Some(token) = self.peek()? else {
                break;
            };

            let (precedence, is_right_associative) = match token {
                Token::Keyword(Keyword::And) => (5, false),
                Token::Keyword(Keyword::Or) => (1, false),
                Token::Equal | Token::NotEqual | Token::LessThan | Token::LessThanOrEqual | Token::GreaterThan | Token::GreaterThanOrEqual | Token::Keyword(Keyword::Like) => (3, false),
                Token::Keyword(Keyword::Is) => (4, true),
                Token::Plus | Token::Minus => (6, false),
                Token::Asterisk | Token::Slash | Token::Percent => (7, false),
                Token::Caret => (8, true),
                Token::Exclamation => (9, false), // Postfix factorial
                _ => break,
            };

            if precedence < min_precedence {
                break;
            }

            self.next(); // consume the operator token

            if precedence == 9 {
                // Postfix factorial
                lhs = ast::Expression::Operator(ast::Operator::Factorial(Box::new(lhs)));
                continue;
            }

            let rhs = if is_right_associative {
                self.parse_precedence(precedence)?
            } else {
                self.parse_precedence(precedence + 1)?
            };

            lhs = match token {
                Token::Keyword(Keyword::And) => ast::Expression::Operator(ast::Operator::And(Box::new(lhs), Box::new(rhs))),
                Token::Keyword(Keyword::Or) => ast::Expression::Operator(ast::Operator::Or(Box::new(lhs), Box::new(rhs))),
                Token::Equal => ast::Expression::Operator(ast::Operator::Equal(Box::new(lhs), Box::new(rhs))),
                Token::NotEqual => ast::Expression::Operator(ast::Operator::NotEqual(Box::new(lhs), Box::new(rhs))),
                Token::LessThan => ast::Expression::Operator(ast::Operator::LessThan(Box::new(lhs), Box::new(rhs))),
                Token::LessThanOrEqual => ast::Expression::Operator(ast::Operator::LessThanOrEqual(Box::new(lhs), Box::new(rhs))),
                Token::GreaterThan => ast::Expression::Operator(ast::Operator::GreaterThan(Box::new(lhs), Box::new(rhs))),
                Token::GreaterThanOrEqual => ast::Expression::Operator(ast::Operator::GreaterThanOrEqual(Box::new(lhs), Box::new(rhs))),
                Token::Keyword(Keyword::Like) => ast::Expression::Operator(ast::Operator::Like(Box::new(lhs), Box::new(rhs))),
                Token::Keyword(Keyword::Is) => {
                    // IS NULL or IS NAN
                    let literal = match self.next()? {
                        Token::Keyword(Keyword::Null) => ast::Literal::Null,
                        Token::Keyword(Keyword::NaN) => ast::Literal::Float(f64::NAN),
                        Token::Keyword(Keyword::Infinity) => ast::Literal::Float(f64::INFINITY),
                        other => return errinput!("expected NULL or NaN after IS, got {}", other),
                    };
                    ast::Expression::Operator(ast::Operator::Is(Box::new(lhs), literal))
                }
                Token::Plus => ast::Expression::Operator(ast::Operator::Add(Box::new(lhs), Box::new(rhs))),
                Token::Minus => ast::Expression::Operator(ast::Operator::Subtract(Box::new(lhs), Box::new(rhs))),
                Token::Asterisk => ast::Expression::Operator(ast::Operator::Multiply(Box::new(lhs), Box::new(rhs))),
                Token::Slash => ast::Expression::Operator(ast::Operator::Divide(Box::new(lhs), Box::new(rhs))),
                Token::Percent => ast::Expression::Operator(ast::Operator::Remainder(Box::new(lhs), Box::new(rhs))),
                Token::Caret => ast::Expression::Operator(ast::Operator::Exponentiate(Box::new(lhs), Box::new(rhs))),
                _ => break,
            };
        }

        Ok(lhs)
    }

    /// Parses a primary expression (literals, columns, functions, etc.).
    fn parse_primary(&mut self) -> Result<ast::Expression> {
        let token = self.next()?;

        match token {
            Token::Asterisk => Ok(ast::Expression::All),
            Token::Ident(name) => {
                // Check if it's a qualified column name (table.column)
                if self.next_is(Token::Period) {
                    let column = self.next_ident()?;
                    Ok(ast::Expression::Column(Some(name), column))
                } else {
                    Ok(ast::Expression::Column(None, name))
                }
            }
            Token::Number(n) => {
                if n.contains('.') || n.contains('e') || n.contains('E') {
                    Ok(ast::Expression::Literal(ast::Literal::Float(n.parse()?)))
                } else {
                    Ok(ast::Expression::Literal(ast::Literal::Integer(n.parse()?)))
                }
            }
            Token::String(s) => Ok(ast::Expression::Literal(ast::Literal::String(s))),
            Token::Keyword(Keyword::Null) => Ok(ast::Expression::Literal(ast::Literal::Null)),
            Token::Keyword(Keyword::True) => Ok(ast::Expression::Literal(ast::Literal::Boolean(true))),
            Token::Keyword(Keyword::False) => Ok(ast::Expression::Literal(ast::Literal::Boolean(false))),
            Token::Keyword(Keyword::NaN) => Ok(ast::Expression::Literal(ast::Literal::Float(f64::NAN))),
            Token::Keyword(Keyword::Infinity) => Ok(ast::Expression::Literal(ast::Literal::Float(f64::INFINITY))),
            Token::Minus => {
                let expr = self.parse_primary()?;
                Ok(ast::Expression::Operator(ast::Operator::Negate(Box::new(expr))))
            }
            Token::Plus => {
                let expr = self.parse_primary()?;
                Ok(ast::Expression::Operator(ast::Operator::Identity(Box::new(expr))))
            }
            Token::Keyword(Keyword::Not) => {
                let expr = self.parse_primary()?;
                Ok(ast::Expression::Operator(ast::Operator::Not(Box::new(expr))))
            }
            Token::OpenParen => {
                // Check for function call
                if let Some(Token::Ident(name)) = self.peek()?.cloned() {
                    self.next();
                    self.expect(Token::OpenParen)?;

                    let mut args = Vec::new();
                    if !self.next_is(Token::CloseParen) {
                        loop {
                            args.push(self.parse_expression()?);
                            if !self.next_is(Token::Comma) {
                                break;
                            }
                        }
                    }

                    self.expect(Token::CloseParen)?;
                    Ok(ast::Expression::Function(name, args))
                } else {
                    // Parenthesized expression
                    let expr = self.parse_expression()?;
                    self.expect(Token::CloseParen)?;
                    Ok(expr)
                }
            }
            other => errinput!("unexpected token in expression: {}", other),
        }
    }
